import QRCode from 'qrcode';
import {Cpu,Layers,FlaskConical,BookOpen,Truck,ShieldCheck,Recycle,ChartNoAxesCombined,Plus,Search,X,ArrowUpRight,Download,Printer,QrCode,Link,ClipboardCheck,Timer,Settings2,Building2} from 'lucide-react';
