function ComponentDecisions({data,user,order,run}:Any){const [channel,setChannel]=useState('Presencial');const components=Array.from(new Set(order.items.map((i:Any)=>i.component).filter(Boolean))) as string[];return <div className="asic-subsection">{user.role!=='Cliente'&&<label className="field"><span>Canal da decisão</span><select value={channel} onChange={e=>setChannel(e.target.value)}>{['Presencial','WhatsApp','Telefone','E-mail'].map(x=><option key={x}>{x}</option>)}</select></label>}{components.map(id=>{const lines=order.items.filter((i:Any)=>i.component===id);return <article className="component-decision" key={id}><div><strong>{get(data,'assets',id)?.code} · {get(data,'assets',id)?.kind}</strong><p>{lines.map((i:Any)=>i.description).join(' · ')}</p>{lines.filter((i:Any)=>i.comment).map((i:Any,k:number)=><small className="sub" key={k}>{i.description}: {i.comment}{user.role!=='Cliente'&&<em className={i.commentVisible?'':'hiddenmark'}> · {i.commentVisible?'visível ao cliente':'oculto ao cliente'}</em>}</small>)}{user.role!=='Cliente'&&lines.some((i:Any)=>i.free)&&<Pill>fora da tabela</Pill>} <Pill>{lines[0].decision||'Pendente'}</Pill> <span>{brl(lines.reduce((v:number,i:Any)=>v+i.qty*i.price,0))}</span><small className="sub">Garantia: {lines.map((i:Any)=>i.warranty+' dias').join(', ')}</small></div>{!['Entregue','Cancelado'].includes(order.status)&&(user.role==='Cliente'?user.canApprove:user.can?.decidirOrcamento)&&<div className="asic-actions">{['Aprovado','Recusado'].map(decision=><button className="btn" key={decision} onClick={()=>{if(confirm('Confirmar '+decision.toLowerCase()+' para este componente?'))run('decision',{order:order.id,component:id,decision,channel})}}>{decision==='Aprovado'?'Aprovar':'Recusar'}</button>)}</div>}</article>})}{!components.length&&<p className="muted">Nenhum orçamento por componente nesta OS.</p>}</div>}
function QuoteEditor({data,order,run,onClose,externalError,user}:Any){
 const table=(data.priceItems||[]).filter((p:Any)=>p.active!==false),noCost=!user?.can?.verCustos,noDiscount=!user?.can?.decidirOrcamento,blank=()=>({component:'',priceItem:'',description:'',qty:1,price:0,cost:0,warranty:0,comment:'',commentVisible:false});
 const [items,setItems]=useState<Any[]>(order.items.length?order.items.map((i:Any)=>({component:i.component,priceItem:i.priceItem||'free',description:i.description,qty:i.qty,price:i.price,cost:i.cost||0,warranty:i.warranty??0,comment:i.comment||'',commentVisible:i.commentVisible===true})):[blank()]),[discount,setDiscount]=useState(order.discount),[busy,setBusy]=useState(false);
 const set=(n:number,patch:Any)=>setItems(items.map((x,i)=>i===n?{...x,...patch}:x)),isTable=(i:Any)=>!!i.priceItem&&i.priceItem!=='free',pick=(i:Any)=>table.find((p:Any)=>p.id===i.priceItem),unit=(i:Any)=>isTable(i)?(pick(i)?.price??0):Number(i.price)||0;
 const send=(i:Any)=>isTable(i)?{component:i.component,priceItem:i.priceItem,qty:i.qty,comment:i.comment,commentVisible:i.commentVisible}:{component:i.component,description:i.description,qty:i.qty,price:i.price,cost:i.cost,warranty:i.warranty,comment:i.comment,commentVisible:i.commentVisible};
 return <div className="overlay"><section className="modal wide"><div className="modalhead"><h2>Orçamento por componente · {oscode(order)}</h2><button className="iconbtn" onClick={onClose} aria-label="Fechar"><X/></button></div>{externalError&&<div className="alert" role="alert">{externalError}</div>}
 {!table.length&&<p className="muted">A tabela de preços está vazia. Use “Outro item” ou peça ao administrador para cadastrar os itens.</p>}
 <form onSubmit={async e=>{e.preventDefault();setBusy(true);if(await run('quote',{order:order.id,items:items.map(send),discount}))onClose();setBusy(false)}}>{items.map((item:Any,n:number)=><section className="quote-component card padding" key={n}><div className="formgrid">
  <label className="field"><span>Componente</span><select required value={item.component} onChange={e=>set(n,{component:e.target.value})}><option value="">Selecionar</option>{(order.assetIds||[]).map((id:string)=><option value={id} key={id}>{assetName(get(data,'assets',id))}</option>)}</select></label>
  <label className="field"><span>Item da tabela de preços</span><select required value={item.priceItem} onChange={e=>set(n,{priceItem:e.target.value})}><option value="">Selecionar</option>{['Serviço','Peça'].map(cat=>table.some((p:Any)=>p.category===cat)&&<optgroup key={cat} label={cat==='Peça'?'Peças':'Serviços'}>{table.filter((p:Any)=>p.category===cat).map((p:Any)=><option key={p.id} value={p.id}>{p.name} — {brl(p.price)}</option>)}</optgroup>)}<option value="free">Outro item (fora da tabela)</option></select></label>
  <label className="field"><span>Quantidade</span><input required type="number" min="0.01" step="any" value={item.qty} onChange={e=>set(n,{qty:e.target.value})}/></label>
  {isTable(item)&&(pick(item)?<div className="field"><span>Preço e garantia (da tabela)</span><output className="pricepreview">{brl(unit(item))} por unidade · garantia {pick(item).warranty} dias</output></div>:<p className="alert" role="alert">Este item foi desativado na tabela. Escolha outro ou use “Outro item”.</p>)}
  {item.priceItem==='free'&&<><p className="full freebanner">Item fora da tabela: ficará marcado para conferência do atendimento.</p>
   <label className="field"><span>Descrição</span><input required value={item.description} onChange={e=>set(n,{description:e.target.value})}/></label>
   <label className="field"><span>Preço unitário (R$)</span><input required type="number" min="0" step="any" value={item.price} onChange={e=>set(n,{price:e.target.value})}/></label>
   {!noCost&&<label className="field"><span>Custo interno unitário (R$)</span><input type="number" min="0" step="any" value={item.cost} onChange={e=>set(n,{cost:e.target.value})}/></label>}
   <label className="field"><span>Garantia (dias)</span><input required type="number" min="0" step="1" value={item.warranty} onChange={e=>set(n,{warranty:e.target.value})}/></label></>}
  <label className="field full"><span>Comentário do item (opcional)</span><textarea rows={2} maxLength={2000} value={item.comment} onChange={e=>set(n,{comment:e.target.value})}/></label>
  <label className="checkline full"><input type="checkbox" checked={item.commentVisible} disabled={!item.comment} onChange={e=>set(n,{commentVisible:e.target.checked})}/><span>Mostrar este comentário ao cliente <small>(desmarcado, fica oculto e só a equipe vê)</small></span></label>
 </div><button type="button" className="textbtn" onClick={()=>setItems(items.filter((_,i)=>i!==n))}>Remover item</button></section>)}
 <button type="button" className="btn" onClick={()=>setItems([...items,blank()])}><Plus size={14}/> Adicionar item</button>
 <div className="inlineform"><label className="field"><span>Desconto global (R$){noDiscount?' — definido pelo atendimento':''}</span><input type="number" min="0" step="0.01" value={discount} disabled={noDiscount} onChange={e=>setDiscount(Number(e.target.value))}/></label><strong>Total: {brl(items.reduce((v:number,i:Any)=>v+(Number(i.qty)||0)*unit(i),0)-discount)}</strong><button disabled={busy} className="btn primary">Salvar e exigir nova aprovação</button></div></form></section></div>}
export function downloadCSV(rows:Any[],name:string){const safe=(v:Any)=>{let x=String(v??'');if(/^[=+@\-\t\r]/.test(x))x="'"+x;return '"'+x.replaceAll('"','""')+'"'};const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();URL.revokeObjectURL(url)}
export function ClientPortal({data:s,user:u,act,refresh,externalError}:Any){const [tab,setTab]=useState('Meus equipamentos'),[selected,setSelected]=useState(''),[error,setError]=useState('');const o=get(s,'orders',selected);const run=async(action:string,p:Any)=>{try{return await act('asic_'+action,p)}catch(e:Any){setError(e.message);return false}};return <div className="portal"><header><div className="brand"><Cpu size={27}/> bancada<span>ASIC</span></div><div className="portal-identity"><strong>{get(s,'clients',u.client)?.name}</strong><small>{u.name} · {u.canApprove?'Aprovador':'Consulta'}</small></div><SessionActions/></header><main><div className="pageheading"><div><span className="eyebrow">PORTAL DA FAZENDA / {s.settings.name}</span><h1>Sua operação, acompanhada.</h1><p>Equipamentos, lotes, orçamentos e laudos da sua empresa.</p></div><button className="btn" onClick={refresh}>Atualizar</button></div>{(error||externalError)&&<div className="alert">{error||externalError}</div>}<div className="metrics">{[['Equipamentos',s.assets.length],['Em atendimento',s.orders.filter((o:Any)=>!['Entregue','Cancelado'].includes(o.status)).length],['Aprovações pendentes',s.orders.filter((o:Any)=>o.items.some((i:Any)=>i.decision==='Pendente')).length],['Saldo a pagar',brl(s.orders.filter((o:Any)=>o.status!=='Cancelado').reduce((v:number,o:Any)=>v+total(o)-paid(o),0))]].map(([k,v])=><article className="metric" key={String(k)}><p className="muted">{k}</p><div className="metricvalue">{v}</div></article>)}</div><div className="asic-nav">{['Meus equipamentos','Ordens e orçamentos','Lotes e transporte','Contratos e visitas'].map(t=><button key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==='Meus equipamentos'&&<section className="card"><Records items={s.assets} columns={[["IDENTIFICAÇÃO",'code'],["TIPO",'kind'],["MODELO",'model'],["SÉRIE",'serial'],["ESTADO",'status']]}/></section>}{tab==='Ordens e orçamentos'&&<><section className="card"><Records items={s.orders} onClick={(o:Any)=>setSelected(o.id)} columns={[["OS",oscode],["ESTADO",'status'],["PREVISÃO",(o:Any)=>date(o.due)],["TOTAL",(o:Any)=>brl(total(o))],["SALDO",(o:Any)=>brl(total(o)-paid(o))]]}/></section>{o&&<section className="card padding spaced"><h2>{oscode(o)}</h2><p>{o.publicNote||'Sua assistência atualizará as informações aqui.'}</p>{(o.comments||[]).length>0&&<div className="asic-subsection"><h3>Mensagens da assistência</h3>{[...o.comments].reverse().map((c:Any)=><div className="history" key={c.id}><span>{date(c.at)}</span><p>{c.text}</p></div>)}</div>}<TechnicalReport data={s} order={o} customer/><ComponentDecisions data={s} user={u} order={o} run={run}/><Uploads scope="order" record={o} refresh={refresh} customer/></section>}</>}{tab==='Lotes e transporte'&&<><section className="card"><Records items={s.lots} columns={[["LOTE",'code'],["REMESSA",'name'],["CONFERIDOS",(l:Any)=>l.assets.length+'/'+l.expected],["ESTADO",(l:Any)=>l.closed?'Encerrado':'Aberto']]}/></section><section className="card spaced"><Records items={s.shipments} columns={[["TRANSPORTADORA",'carrier'],["RASTREAMENTO",'tracking'],["ESTADO",'status'],["UNIDADES",(sh:Any)=>sh.assets.length]]}/></section></>}{tab==='Contratos e visitas'&&<><section className="card"><Records items={s.contracts} columns={[["CONTRATO",'name'],["SLA",(c:Any)=>c.slaHours+' h'],["LIMITE DE APROVAÇÃO",(c:Any)=>brl(c.approvalLimit)],["VIGÊNCIA ATÉ",(c:Any)=>date(c.end)],["CONDIÇÕES",'terms']]}/></section><section className="card spaced"><Records items={s.visits} columns={[["ATENDIMENTO",'task'],["DATA",(v:Any)=>date(v.scheduled)],["LOCAL",'location'],["ESTADO",'status'],["PRÓXIMA PREVENTIVA",(v:Any)=>date(v.nextDate)]]}/></section></>}<p className="muted spaced">Orçamentos são aprovados conforme seu perfil, o contrato vigente e o limite autorizado por OS. O portal não processa pagamentos.</p></main><CreditFooter/></div>}
